{"command": "python3 << 'PYEOF'
import json

# FT2 note mapping (C-1=1, B-1=12, C-2=13... C-4=37, A-4=45, A-5=57)
def n(oct, note):
    return (oct + 1) * 12 + note

# Notes in A minor scale: A, B, C, D, E, F, G
A_MINOR = {
    'C3': n(3,1), 'D3': n(3,3), 'E3': n(3,5), 'G3': n(3,8), 'A3': n(3,11),
    'C4': n(4,1), 'D4': n(4,3), 'E4': n(4,5), 'G4': n(4,8), 'A4': n(4,11),
    'C5': n(5,1), 'D5': n(5,3), 'E5': n(5,5), 'G5': n(5,8), 'A5': n(5,11),
    'C6': n(6,1), 'D6': n(6,3), 'E6': n(6,5), 'G6': n(6,8), 'A6': n(6,11),
}

# Off value
OFF = 0

# Pattern definitions
# Format: {pattern_idx: {row: {channel: (note, instrument, vol, effect, param)}}}

# First, let's create 4 patterns of 64 rows each
patterns = {}

# Pattern 0: Intro - crash + basic beat
pat0 = {}
for row in range(64):
    pat0[row] = {}
    # Crash on row 0
    if row == 0:
        pat0[row][6] = (A_MINOR['A5'], 7, 60, 0, 0)
    # Kick on every 4 rows (1, 17, 33, 49)
    if row % 16 in [0, 4, 8, 12]:
        pat0[row][3] = (OFF, 1, 64, 0, 0)
    # Snare on beats 2 and 4
    if row % 16 in [8]:
        pat0[row][4] = (OFF, 2, 64, 0, 0)
    # Hi-hat on every other row
    if row % 2 == 0:
        pat0[row][5] = (OFF, 3, 40, 0, 0)
patterns[0] = pat0

# Pattern 1: Main beat + bass + arp intro
pat1 = {}
for row in range(64):
    pat1[row] = {}
    # Kick pattern: 1, 5, 9, 13 for a driving feel
    if row % 16 in [0, 4, 8, 12]:
        pat1[row][3] = (OFF, 1, 64, 0, 0)
    # Snare on 2 and 4
    if row % 16 in [8]:
        pat1[row][4] = (OFF, 2, 64, 0, 0)
    # Hi-hat 16ths
    if row % 2 == 0:
        pat1[row][5] = (OFF, 3, 35, 0, 0)
    # Bass line - A minor power pattern
    if row % 4 == 0:
        if row % 16 in [0, 8]:
            pat1[row][2] = (A_MINOR['A3'], 6, 60, 0, 0)
        elif row % 16 in [4, 12]:
            pat1[row][2] = (A_MINOR['E3'], 6, 55, 0, 0)
    # Arp - fast 16th notes
    if row % 4 in [1, 2, 3]:
        notes_arp = [A_MINOR['A4'], A_MINOR['C5'], A_MINOR['E5']]
        arp_idx = (row % 12) % 3
        pat1[row][1] = (notes_arp[arp_idx], 5, 45, 0, 0)
patterns[1] = pat1

# Pattern 2: Full arrangement with lead melody
pat2 = {}
# Lead melody sequence (in 16ths, 4 rows per note)
melody = [
    (A_MINOR['A5'], 16), (A_MINOR['E5'], 8), (A_MINOR['C5'], 8),
    (A_MINOR['E5'], 8), (A_MINOR['D5'], 8), (A_MINOR['C5'], 8), (A_MINOR['D5'], 8),
    (A_MINOR['E5'], 8), (A_MINOR['G5'], 16), (A_MINOR['E5'], 8),
    (A_MINOR['C5'], 8), (A_MINOR['D5'], 8), (A_MINOR['C5'], 8), (A_MINOR['A4'], 8),
    (A_MINOR['C5'], 8), (A_MINOR['E5'], 8), (A_MINOR['A5'], 16)
]

note_idx = 0
note_rows_left = 0
current_note = OFF

for row in range(64):
    pat2[row] = {}

    # Kick
    if row % 16 in [0, 4, 8, 12]:
        pat2[row][3] = (OFF, 1, 64, 0, 0)
    # Snare
    if row % 16 in [8]:
        pat2[row][4] = (OFF, 2, 64, 0, 0)
    # Hi-hat
    if row % 2 == 0:
        pat2[row][5] = (OFF, 3, 35, 0, 0)
    # Bass
    if row % 4 == 0:
        if row % 16 in [0, 8]:
            pat2[row][2] = (A_MINOR['A3'], 6, 60, 0, 0)
        elif row % 16 in [4, 12]:
            pat2[row][2] = (A_MINOR['E3'], 6, 55, 0, 0)
    # Arp
    if row % 2 == 1:
        notes_arp = [A_MINOR['A4'], A_MINOR['C5'], A_MINOR['E5']]
        arp_idx = (row // 2) % 3
        pat2[row][1] = (notes_arp[arp_idx], 5, 40, 0, 0)
    # Lead melody
    if note_rows_left > 0:
        note_rows_left -= 1
        if note_rows_left == 0:
            note_idx += 1
    if note_idx < len(melody) and note_rows_left == 0:
        current_note, note_rows_left = melody[note_idx]
        if note_rows_left > 0:
            note_rows_left -= 1
            pat2[row][0] = (current_note, 4, 64, 0, 0)
            if note_rows_left == 0:
                note_idx += 1
    elif note_rows_left > 0:
        pat2[row][0] = (current_note, 4, 64, 0, 0)
patterns[2] = pat2

# Pattern 3: Variation - different melody and more energy
pat3 = {}
melody2 = [
    (A_MINOR['E5'], 8), (A_MINOR['G5'], 8), (A_MINOR['A5'], 16), (A_MINOR['E5'], 8),
    (A_MINOR['D5'], 8), (A_MINOR['E5'], 8), (A_MINOR['C5'], 8), (A_MINOR['D5'], 16),
    (A_MINOR['A4'], 8), (A_MINOR['C5'], 8), (A_MINOR['D5'], 8), (A_MINOR['E5'], 8),
    (A_MINOR['G5'], 8), (A_MINOR['A5'], 16), (A_MINOR['E5'], 8), (A_MINOR['D5'], 8),
]

note_idx = 0
note_rows_left = 0
current_note = OFF

for row in range(64):
    pat3[row] = {}

    # Kick - more driving
    if row % 16 in [0, 3, 8, 11]:
        pat3[row][3] = (OFF, 1, 64, 0, 0)
    # Snare
    if row % 16 in [8]:
        pat3[row][4] = (OFF, 2, 64, 0, 0)
    # Hi-hat - more intensity
    if row % 2 == 0:
        pat3[row][5] = (OFF, 3, 40, 0, 0)
    else:
        pat3[row][5] = (OFF, 3, 25, 0, 0)
    # Bass - syncopated
    if row % 16 in [0, 6, 8, 14]:
        if row % 16 in [0, 8]:
            pat3[row][2] = (A_MINOR['A3'], 6, 60, 0, 0)
        else:
            pat3[row][2] = (A_MINOR['G3'], 6, 55, 0, 0)
    # Arp - faster
    notes_arp = [A_MINOR['A4'], A_MINOR['C5'], A_MINOR['E5'], A_MINOR['G4']]
    arp_idx = row % 4
    pat3[row][1] = (notes_arp[arp_idx], 5, 35, 0, 0)
    # Lead melody
    if note_rows_left > 0:
        note_rows_left -= 1
        if note_rows_left == 0:
            note_idx += 1
    if note_idx < len(melody2) and note_rows_left == 0:
        current_note, note_rows_left = melody2[note_idx]
        if note_rows_left > 0:
            note_rows_left -= 1
            pat3[row][0] = (current_note, 4, 64, 0, 0)
            if note_rows_left == 0:
                note_idx += 1
    elif note_rows_left > 0:
        pat3[row][0] = (current_note, 4, 64, 0, 0)
patterns[3] = pat3

# Save patterns to JSON for inspection
print("Pattern 0 rows:", len(pat0))
print("Pattern 1 rows:", len(pat1))
print("Pattern 2 rows:", len(pat2))
print("Pattern 3 rows:", len(pat3))

# Save the patterns data
with open('/workspace/patterns.json', 'w') as f:
    json.dump(patterns, f)
print("Patterns saved to /workspace/patterns.json")
PYEOF"}

